import numpy as np

def step(lam,w,s):
    # w squared error directions
    V=np.array([lam**j for j in range(1,s+1)]).T
    c=np.linalg.solve(V.T@(w[:,None]*V),-V.T@w)
    p=1+V@c
    f=w@(p*p)
    return w*p*p/f, p, f
if __name__=='__main__':
 rng=np.random.default_rng(3)
 for s in [2,3,4]:
  for n in [2*s,2*s+1,3*s]:
   best=0; record=None
   for it in range(20):
    lam=np.sort(rng.uniform(.1,2,n)); w=rng.dirichlet(np.ones(n)); prev=None
    for k in range(5000):
     w,p,f=step(lam,w,s)
     if k==3999: prev=w.copy()
    dif=np.linalg.norm(w-prev)
    if dif>best: best=dif; record=(lam,w,f)
   print(s,n,best,record,flush=True)

