from itertools import product
z=np.array([-3.,-2.,-1.,1.,2.,3.]);R=np.poly(z);Rp=np.polyder(R)
V=np.array([z**j for j in range(3)]).T;M=np.array([np.outer(v,v) for v in V]);B0=V*z[:,None]**3

def step(w):
 c=np.linalg.solve(np.einsum('i,ijk->jk',w,M),-w@B0)
 p=z**3+V@c;w=w*p*p;return w/sum(w)
for delta in [.01,.1,1,3,5]:
 roots=np.sort(np.r_[np.roots([1,0,-7,-delta]),np.roots([1,0,-7,delta])])
 for bits in product([0,1],repeat=3):
  proots=roots[[2*j+b for j,b in enumerate(bits)]];qroots=roots[[2*j+1-b for j,b in enumerate(bits)]]
  found=False
  for f1 in [.1,.5,.9]:
   for f2 in [.1,.5,.9]:
    beta=np.array([z[1]*(1-f1)+z[2]*f1,z[3]*(1-f2)+z[4]*f2])
    w=np.polyval(np.poly(qroots),z)*np.polyval(np.poly(beta),z)/np.polyval(Rp,z);w/=sum(w)
    if min(w)<0: continue
    J=np.column_stack([(step(step(w+np.eye(6)[i]*1e-6))-step(step(w-np.eye(6)[i]*1e-6)))/2e-6 for i in range(6)])
    ev=np.linalg.eigvals(J)
    if max(abs(ev.imag))>.0001:
     print('elliptic',delta,bits,f1,f2,ev,w,flush=True);found=True;break
   if found:break
